<script lang="ts">
 import DashboardContent from '$lib/components/DashboardContent.svelte'; import { Button } from '$lib/components/ui/button/index.js'; import { Plus, UserPlus, XCircle, CheckCircle2 } from 'lucide-svelte'; import { enhance } from '$app/forms'; import { dispatchToast } from '$lib/notifications';
 const { data } = $props(); const admissions = $derived(data.admissions); const classes = $derived(data.classes); const years = $derived(data.years); let open = $state(false); let submitting = $state(false);
 function submit(){submitting=true;return async({update,result}:any)=>{if(result.type==='success'){open=false;dispatchToast('Saved',result.data?.message??'Saved')}else if(result.type==='failure')dispatchToast('Error',result.data?.message??'Please check the form.');await update();submitting=false;};}
</script>
<DashboardContent title="Admissions" subtitle="Application → admission decision → enrollment. No screening stage.">
{#snippet headerActions()}<Button onclick={()=>open=true} size="sm"><Plus class="h-3.5 w-3.5"/> New Application</Button>{/snippet}
<div class="mb-5 grid grid-cols-2 gap-3 md:grid-cols-4"><div class="card"><p>Pending</p><strong>{admissions.filter((a:any)=>a.status==='pending').length}</strong></div><div class="card"><p>Approved</p><strong>{admissions.filter((a:any)=>a.status==='approved').length}</strong></div><div class="card"><p>Enrolled</p><strong>{admissions.filter((a:any)=>a.status==='enrolled').length}</strong></div><div class="card"><p>Total</p><strong>{admissions.length}</strong></div></div>
<div class="overflow-hidden rounded-xl border border-border bg-white"><div class="grid grid-cols-[1fr_1.6fr_1fr_1fr_auto] gap-3 border-b bg-muted/40 px-4 py-3 text-xs font-semibold text-muted-foreground"><span>Application</span><span>Applicant</span><span>Academic Year</span><span>Status</span><span></span></div>{#each admissions as a}<div class="grid grid-cols-[1fr_1.6fr_1fr_1fr_auto] items-center gap-3 border-b px-4 py-3 last:border-0"><div><p class="text-sm font-medium">{a.application_no??a.admission_number}</p><p class="text-[11px] text-muted-foreground">{a.admission_date}</p></div><div><p class="text-sm font-medium">{a.applicant_first_name?`${a.applicant_first_name} ${a.applicant_middle_name??''} ${a.applicant_last_name??''}`:a.students?`${a.students.first_name} ${a.students.last_name}`:'Applicant'}</p><p class="text-[11px] text-muted-foreground">{a.phone??'No phone'}</p></div><span class="text-sm">{a.academic_year??'—'}</span><span class="inline-flex w-fit rounded-full bg-muted px-2 py-1 text-xs capitalize">{a.status}</span><div class="flex gap-1">{#if a.status==='pending'||a.status==='approved'}<form method="POST" action="?/admit" use:enhance><input type="hidden" name="id" value={a.id}/><input type="hidden" name="admission_no" value={a.admission_number??a.application_no}/><Button size="icon" variant="ghost" title="Admit"><UserPlus class="h-4 w-4"/></Button></form><form method="POST" action="?/reject" use:enhance><input type="hidden" name="id" value={a.id}/><Button size="icon" variant="ghost" title="Reject"><XCircle class="h-4 w-4"/></Button></form>{:else if a.status==='enrolled'}<CheckCircle2 class="h-4 w-4 text-primary"/>{/if}</div></div>{:else}<div class="p-12 text-center text-sm text-muted-foreground">No applications yet.</div>{/each}</div>
</DashboardContent>
{#if open}<div class="fixed inset-0 z-50 flex items-center justify-center bg-black/30 p-4"><div class="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white shadow-xl"><div class="border-b px-6 py-4"><h2 class="font-semibold">New Admission Application</h2><p class="text-xs text-muted-foreground">Direct admissions workflow — there is intentionally no screening step.</p></div><form method="POST" action="?/create" use:enhance={submit} class="grid gap-4 px-6 py-5 md:grid-cols-2"><label class="field-label">Application No<input name="application_no" required class="field" placeholder="APP-2026-001"/></label><label class="field-label">Academic Year<input name="academic_year" list="years" required class="field" placeholder="2027"/></label><datalist id="years">{#each years as y}<option value={y}/>{/each}</datalist><label class="field-label">First Name<input name="applicant_first_name" required class="field"/></label><label class="field-label">Middle Name<input name="applicant_middle_name" class="field"/></label><label class="field-label">Last Name<input name="applicant_last_name" required class="field"/></label><label class="field-label">Date of Birth<input name="date_of_birth" type="date" class="field"/></label><label class="field-label">Gender<select name="gender" class="field"><option value="">Not specified</option><option>Female</option><option>Male</option><option>Other</option></select></label><label class="field-label">Phone<input name="phone" class="field"/></label><label class="field-label">Email<input name="email" type="email" class="field"/></label><label class="field-label md:col-span-2">Applying For<select name="class_id" class="field"><option value="">Select class</option>{#each classes as c}<option value={c.id}>{c.name}{c.stream?` · ${c.stream}`:''} {c.academic_year?` · ${c.academic_year}`:''}</option>{/each}</select></label><label class="field-label">Previous School<input name="previous_school" class="field"/></label><label class="field-label">Guardian Name<input name="guardian_name" class="field"/></label><label class="field-label">Guardian Relationship<input name="guardian_relationship" class="field" placeholder="Mother"/></label><label class="field-label">Guardian Phone<input name="guardian_phone" class="field"/></label><label class="field-label md:col-span-2">Notes<textarea name="notes" rows="3" class="field"></textarea></label><div class="flex justify-end gap-2 md:col-span-2"><Button type="button" variant="outline" onclick={()=>open=false}>Cancel</Button><Button type="submit" disabled={submitting}>{submitting?'Saving…':'Create Application'}</Button></div></form></div></div>{/if}
